// ─── File: AuthDemo.java ───
package com.bank.auth;

import java.util.*;
import java.util.logging.*;

public class AuthDemo {
    private static final Logger log = Logger.getLogger(AuthDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // In Spring this Map is injected automatically (bean name → strategy).
        // Here we build it by hand to show the same wiring.
        Map<String, AuthenticationStrategy> strategies = new HashMap<>();
        for (AuthenticationStrategy s : List.of(
                new PasswordAuthStrategy(), new OtpAuthStrategy(), new CaptchaAuthStrategy()))
            strategies.put(s.type(), s);

        AuthController controller = new AuthController(strategies);

        // Same endpoint/handler, different authType selected at runtime
        controller.login(new AuthRequest("PASSWORD", "SAV2001", Map.of("password", "rajesh@123")));
        controller.login(new AuthRequest("OTP",      "CUR3001", Map.of("otp", "482913")));
        controller.login(new AuthRequest("CAPTCHA",  "SAV2001", Map.of("captcha", "X7KQ", "password", "rajesh@123")));

        // OPEN/CLOSED: add FACE as a new strategy — handler NOT modified
        strategies.put("FACE", new AuthenticationStrategy() {
            public AuthResult authenticate(AuthRequest r) {
                return new AuthResult(true, "FACE match for " + r.userId());
            }
            public String type() { return "FACE"; }
        });
        controller.login(new AuthRequest("FACE", "SAV2001", Map.of("faceToken", "F-999")));

        // Unknown method is rejected cleanly
        controller.login(new AuthRequest("TELEPATHY", "SAV2001", Map.of()));
    }
}

// ─── Request / Result value objects ───
class AuthRequest {
    private final String authType, userId; private final Map<String,String> credentials;
    AuthRequest(String t, String u, Map<String,String> c){ authType=t; userId=u; credentials=c; }
    String authType(){ return authType; } String userId(){ return userId; }
    Map<String,String> credentials(){ return credentials; }
}
class AuthResult {
    private final boolean success; private final String message;
    AuthResult(boolean s, String m){ success=s; message=m; }
    boolean success(){ return success; } String message(){ return message; }
}

// ─── STRATEGY INTERFACE ───
interface AuthenticationStrategy {
    AuthResult authenticate(AuthRequest request);
    String type();   // the key this strategy handles (== Spring bean name)
}

// ─── CONCRETE STRATEGIES (each isolated) ───
class PasswordAuthStrategy implements AuthenticationStrategy {
    public AuthResult authenticate(AuthRequest r) {
        boolean ok = "rajesh@123".equals(r.credentials().get("password"));
        return new AuthResult(ok, ok ? "Password OK for " + r.userId() : "Bad password");
    }
    public String type(){ return "PASSWORD"; }
}
class OtpAuthStrategy implements AuthenticationStrategy {
    public AuthResult authenticate(AuthRequest r) {
        boolean ok = "482913".equals(r.credentials().get("otp"));
        return new AuthResult(ok, ok ? "OTP verified for " + r.userId() : "Invalid OTP");
    }
    public String type(){ return "OTP"; }
}
class CaptchaAuthStrategy implements AuthenticationStrategy {
    public AuthResult authenticate(AuthRequest r) {
        boolean captchaOk = "X7KQ".equals(r.credentials().get("captcha"));
        boolean pwdOk = "rajesh@123".equals(r.credentials().get("password"));
        boolean ok = captchaOk && pwdOk;
        return new AuthResult(ok, ok ? "CAPTCHA+password OK for " + r.userId() : "CAPTCHA/password failed");
    }
    public String type(){ return "CAPTCHA"; }
}

// ─── SINGLE HANDLER: never changes when methods are added ───
class AuthController {
    private static final Logger log = Logger.getLogger(AuthController.class.getName());
    private final Map<String, AuthenticationStrategy> strategies;   // Spring injects this Map
    AuthController(Map<String, AuthenticationStrategy> strategies){ this.strategies = strategies; }

    void login(AuthRequest request) {
        AuthenticationStrategy strategy = strategies.get(request.authType());
        if (strategy == null) {
            log.warning("Unsupported auth method: " + request.authType());
            return;
        }
        AuthResult result = strategy.authenticate(request);
        if (result.success()) log.info(() -> "LOGIN OK [" + request.authType() + "] " + result.message());
        else log.warning("LOGIN FAIL [" + request.authType() + "] " + result.message());
    }
}

class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
```

Spring wiring note: in a real service each strategy is a bean named after its type, for example `@Component("OTP")`, and the controller declares a constructor parameter `Map<String, AuthenticationStrategy> strategies`; Spring injects a map whose keys are the bean names, so `strategies.get(authType)` dispatches with no switch and new methods are just new beans.
